-- Nominal EIA/JIS LxW package sizes. Height is a nominal library value; series-specific tolerance is noted per package.
CREATE TEMP TABLE IF NOT EXISTS ChipSeed(PackageName TEXT,ComponentType TEXT,Length REAL,Width REAL,Height REAL,Metric TEXT);
DELETE FROM ChipSeed;
INSERT INTO ChipSeed VALUES
