('C01005','Capacitor',0.40,0.20,0.15,'0402'),('C0201','Capacitor',0.60,0.30,0.23,'0603'),('C0402','Capacitor',1.00,0.50,0.55,'1005'),('C0603','Capacitor',1.60,0.80,0.80,'1608'),('C0805','Capacitor',2.00,1.25,0.85,'2012'),('C1206','Capacitor',3.20,1.60,0.85,'3216'),('C1210','Capacitor',3.20,2.50,0.85,'3225'),('C1812','Capacitor',4.50,3.20,0.90,'4532'),('C2220','Capacitor',5.70,5.00,1.00,'5750'),
