UPDATE PackageDefinition SET DisplayName=PackageName,StandardName=PackageName,PackageFamily='CHIP',ComponentType=(SELECT ComponentType FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),Length=(SELECT Length FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),Width=(SELECT Width FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),Height=(SELECT Height FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),BodyLength=(SELECT Length FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),BodyWidth=(SELECT Width FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),PadCount=2,LeadCount=0,IPCName='CHIP',JEDECName=(SELECT Metric FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName),YamahaName='',MirtecAoiClass=upper((SELECT ComponentType FROM ChipSeed s WHERE s.PackageName=PackageDefinition.PackageName)),Description='Standard CHIP package',Notes='Nominal EIA/JIS body dimensions; height is nominal and manufacturer-series dependent.' WHERE PackageName IN (SELECT PackageName FROM ChipSeed);
INSERT OR IGNORE INTO PackageDefinition(PackageName,DisplayName,StandardName,PackageFamily,ComponentType,CategoryId,FamilyId,Length,Width,Height,BodyLength,BodyWidth,PadCount,LeadCount,IPCName,JEDECName,MirtecAoiClass,Description,Notes,IsActive,CreatedAt,UpdatedAt) SELECT s.PackageName,s.PackageName,s.PackageName,'CHIP',s.ComponentType,c.Id,f.Id,s.Length,s.Width,s.Height,s.Length,s.Width,2,0,'CHIP',s.Metric,upper(s.ComponentType),'Standard CHIP package','Nominal EIA/JIS body dimensions; height is nominal and manufacturer-series dependent.',1,datetime('now'),datetime('now') FROM ChipSeed s JOIN PackageCategory c ON c.Code='PASSIVE' JOIN PackageFamily f ON f.CategoryId=c.Id AND f.Code='CHIP';
-- Prefix-specific aliases deliberately avoid generic imperial aliases shared by R/C/L.
INSERT INTO MasterLibrary_PackageAliases(PackageId,Alias,AliasType,Source) SELECT p.Id,lower(substr(p.PackageName,1,1))||'_'||substr(p.PackageName,2),'Footprint','CHIP seed 019' FROM PackageDefinition p WHERE p.PackageName IN (SELECT PackageName FROM ChipSeed) AND NOT EXISTS(SELECT 1 FROM MasterLibrary_PackageAliases a WHERE a.PackageId=p.Id AND lower(a.Alias)=lower(lower(substr(p.PackageName,1,1))||'_'||substr(p.PackageName,2)));
INSERT INTO MasterLibrary_PackageAliases(PackageId,Alias,AliasType,Source) SELECT p.Id,CASE substr(p.PackageName,1,1) WHEN 'R' THEN 'RES'||substr(p.PackageName,2) WHEN 'C' THEN 'CAP'||substr(p.PackageName,2) ELSE 'IND'||substr(p.PackageName,2) END,'Footprint','CHIP seed 019' FROM PackageDefinition p WHERE p.PackageName IN (SELECT PackageName FROM ChipSeed) AND NOT EXISTS(SELECT 1 FROM MasterLibrary_PackageAliases a WHERE a.PackageId=p.Id AND lower(a.Alias)=lower(CASE substr(p.PackageName,1,1) WHEN 'R' THEN 'RES'||substr(p.PackageName,2) WHEN 'C' THEN 'CAP'||substr(p.PackageName,2) ELSE 'IND'||substr(p.PackageName,2) END));
INSERT INTO MasterLibrary_PackageAliases(PackageId,Alias,AliasType,Source) SELECT p.Id,CASE substr(p.PackageName,1,1) WHEN 'R' THEN 'RESC' WHEN 'C' THEN 'CAPC' ELSE 'INDC' END||s.Metric,'Metric','CHIP seed 019' FROM PackageDefinition p JOIN ChipSeed s ON s.PackageName=p.PackageName WHERE NOT EXISTS(SELECT 1 FROM MasterLibrary_PackageAliases a WHERE a.PackageId=p.Id AND lower(a.Alias)=lower(CASE substr(p.PackageName,1,1) WHEN 'R' THEN 'RESC' WHEN 'C' THEN 'CAPC' ELSE 'INDC' END||s.Metric));
DROP TABLE ChipSeed;
